function svgText(x,y,t,size=13,fill="#d9edf8",weight=600,anchor="middle"){return `<text x="${x}" y="${y}" fill="${fill}" font-size="${size}" font-weight="${weight}" text-anchor="${anchor}" font-family="Tahoma,Arial,sans-serif">${escapeHtml(t)}</text>`}
function svgLine(x1,y1,x2,y2,stroke="#63cfe0",w=2){return `<path d="M${x1} ${y1} L${x2} ${y2}" fill="none" stroke="${stroke}" stroke-width="${w}" stroke-linecap="round"/>`}
function svgBox(x,y,w,h,title,sub="",accent="#63cfe0"){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="9" fill="#10283d" stroke="${accent}" stroke-width="1.5"/>${svgText(x+w/2,y+22,title,13,"#effaff",700)}${sub?svgText(x+w/2,y+40,sub,10,"#9bb8ca",500):""}`}
function schematicSvg(kind,side){
 const W=760,H=270;let a=`<svg class="schematic-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${side==="power"?"نقشه مفهومی قدرت":"نقشه مفهومی فرمان"}" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="g-${kind}-${side}" x1="0" x2="1"><stop stop-color="#153b58"/><stop offset="1" stop-color="#0c2033"/></linearGradient></defs><rect x="1" y="1" width="758" height="268" rx="12" fill="url(#g-${kind}-${side})" stroke="#28465e"/>`;
 const line=(x1,y1,x2,y2)=>a+=svgLine(x1,y1,x2,y2);const box=(x,y,w,h,t,s,c)=>a+=svgBox(x,y,w,h,t,s,c);const txt=(x,y,t,z,f)=>a+=svgText(x,y,t,z,f||"#d9edf8");
 if(side==="power"){
   txt(35,25,"L1",11,"#f6c56b");txt(35,45,"L2",11,"#f6c56b");txt(35,65,"L3",11,"#f6c56b");
   [35,50,65].forEach(y=>{line(55,y,105,y);});
   box(105,30,88,52,"QF","حفاظت اصلی","#e4b45d");
   if(kind==="star"){
     line(193,56,230,56);box(230,30,92,52,"KM1","اصلی");line(322,56,365,56);box(365,30,92,52,"OL","اضافه‌بار","#e4b45d");line(457,56,500,56);box(500,30,100,52,"M","موتور سه‌فاز","#7fd7a8");
     line(550,82,550,135);line(550,135,330,135);box(275,135,110,48,"KM-Y","ستاره","#b9a2ff");line(385,159,430,159);box(430,135,110,48,"KM-Δ","مثلث","#b9a2ff");
     txt(380,220,"سه کنتاکتور با اینترلاک و توالی انتقال",12);
   }else if(kind==="reverse"){
     line(193,56,230,56);box(230,25,125,55,"KM-FWD","جهت مستقیم");box(230,105,125,55,"KM-REV","تعویض دو فاز","#b9a2ff");line(355,52,410,52);line(355,132,410,132);line(410,52,410,132);line(410,92,465,92);box(465,66,92,52,"OL","اضافه‌بار","#e4b45d");line(557,92,610,92);box(610,66,95,52,"M","موتور","#7fd7a8");txt(390,205,"اینترلاک مکانیکی + الکتریکی",12);
   }else if(kind==="soft"){
     line(193,56,245,56);box(245,25,170,62,"SS","سافت‌استارتر","#b9a2ff");line(415,56,475,56);box(475,30,90,52,"OL","حفاظت موتور","#e4b45d");line(565,56,615,56);box(615,30,95,52,"M","موتور","#7fd7a8");txt(380,155,"رمپ راه‌اندازی / توقف نرم",12);
   }else{
     line(193,56,250,56);box(250,30,100,52,kind==="emergency"?"K1":"KM","کنتاکتور");line(350,56,410,56);box(410,30,100,52,"OL","حفاظت","#e4b45d");line(510,56,570,56);box(570,30,120,52,"M / LOAD","بار یا موتور","#7fd7a8");
     if(kind==="level"||kind==="manual"||kind==="timer"||kind==="thermostat") {box(250,145,150,52,kind==="level"?"LEVEL":"CONTROL",kind==="level"?"حسگر سطح":kind==="manual"?"انتخاب حالت":kind==="timer"?"زمان‌بند":"ترموستات","#b9a2ff");line(325,145,325,105);txt(470,175,"فرمان از کنترلر به بوبین KM",12);}
     if(kind==="sequence"){box(250,145,150,52,"KM2","موتور دوم","#b9a2ff");txt(470,175,"اجازه راه‌اندازی وابسته به وضعیت KM1",12);}
   }
 }else{
   // Ladder-style control schematic: two vertical rails and readable function blocks.
   line(75,42,75,225);line(685,42,685,225);txt(75,28,"L / +",11,"#f6c56b");txt(685,28,"N / −",11,"#f6c56b");
   const contact=(x,y,t,nc=false)=>{line(x-30,y,x-9,y);line(x+9,y,x+30,y);line(x-8,y-13,x-8,y+13);line(x+8,y-13,x+8,y+13);if(nc)line(x-12,y+12,x+12,y-12);txt(x,y-22,t,10)};
   const coil=(x,y,t)=>{line(x-35,y,x-18,y);a+=`<path d="M${x-18} ${y-15} Q${x-3} ${y} ${x-18} ${y+15} M${x+18} ${y-15} Q${x+3} ${y} ${x+18} ${y+15}" fill="none" stroke="#7fd7a8" stroke-width="2"/>`;line(x+18,y,x+35,y);txt(x,y+32,t,10,"#a7edc4")};
   if(kind==="reverse"){
     [92,155].forEach(y=>{line(75,y,125,y);contact(155,y,"STOP",true);line(185,y,230,y);contact(260,y,y===92?"FWD":"REV");line(290,y,345,y);contact(375,y,y===92?"NC REV":"NC FWD",true);line(405,y,500,y);coil(550,y,y===92?"KM-F":"KM-R");line(585,y,685,y)});txt(380,220,"دو شاخه فرمان با قفل متقابل",11);
   }else if(kind==="star"){
     [85,145,205].forEach((y,i)=>{line(75,y,130,y);if(i===0)contact(160,y,"STOP",true);else line(130,y,190,y);if(i===0){line(190,y,245,y);contact(275,y,"START");line(305,y,380,y);coil(430,y,"KM1");line(465,y,685,y)}else if(i===1){line(190,y,330,y);box(330,y-18,105,36,"TIMER","انتقال");line(435,y,475,y);contact(505,y,"NC Δ",true);line(535,y,570,y);coil(610,y,"KM-Y");line(645,y,685,y)}else{line(190,y,330,y);box(330,y-18,105,36,"TIMER","انتقال");line(435,y,475,y);contact(505,y,"NC Y",true);line(535,y,570,y);coil(610,y,"KM-Δ");line(645,y,685,y)}});txt(380,252,"توالی تایمر و اینترلاک متقابل",10);
   }else{
     line(75,100,120,100);contact(150,100,"STOP",true);line(180,100,225,100);if(kind==="emergency"){contact(255,100,"E-STOP",true);line(285,100,335,100)}else if(kind==="level"||kind==="thermostat"||kind==="timer"||kind==="manual"){contact(255,100,kind==="level"?"LOW":kind==="thermostat"?"TEMP":kind==="timer"?"TIMER":"AUTO");line(285,100,335,100)}else{contact(255,100,"START");line(285,100,335,100)}
     line(335,100,390,100);if(kind==="dol"||kind==="two"||kind==="jog"){contact(365,100,"KM AUX");}else if(kind==="sequence"){contact(365,100,"KM1 OK");}else if(kind==="soft"){box(340,78,100,44,"SS","RUN");}
     line(390,100,485,100);if(kind==="emergency"){box(485,78,105,44,"SAFETY","RELAY","#e4b45d");line(590,100,625,100)}
     coil(635,100,kind==="sequence"?"KM2":kind==="soft"?"SS RUN":kind==="emergency"?"ENABLE":"KM");line(670,100,685,100);
     if(kind==="two"){line(225,100,225,175);line(225,175,270,175);contact(300,175,"START 2");line(330,175,390,175);line(390,175,390,100);txt(455,205,"شاخه استارت دوم موازی",11)}
     if(kind==="jog"){txt(380,190,"بدون خودنگهداری در حالت JOG",11)}
     if(kind==="level"){txt(380,190,"حد بالا: توقف پمپ",11)}
     if(kind==="manual"){txt(380,190,"MANUAL / AUTO با حفاظت مشترک",11)}
     if(kind==="timer"){txt(380,190,"خروجی زمان‌بندی‌شده",11)}
     if(kind==="thermostat"){txt(380,190,"کنترل با نقطه تنظیم و هیسترزیس",11)}
     if(kind==="emergency"){txt(380,190,"بازنشانی جداگانه؛ عدم راه‌اندازی خودکار",11)}
     if(kind==="sequence"){txt(380,190,"شرط اجازه: تأیید وضعیت موتور اول",11)}
   }
 }
 a+=`</svg>`;return a;
}
function renderCircuits(filter=""){const root=$("#circuitGrid");if(!root)return;const list=circuits.filter(c=>(c.name+" "+c.desc+" "+c.parts).toLowerCase().includes(filter.toLowerCase()));root.innerHTML=list.length?list.map(c=>`<article class="circuit-card"><div class="circuit-top"><span class="category">نقشه قدرت و فرمان</span><span class="circuit-code">${c.id.toUpperCase()}</span></div><h3>${escapeHtml(c.name)}</h3><p>${escapeHtml(c.desc)}</p><div class="schematic-pair"><section class="schematic-panel"><div class="schematic-title"><b>نقشه قدرت</b><small>POWER CIRCUIT</small></div>${schematicSvg(c.kind,"power")}</section><section class="schematic-panel"><div class="schematic-title"><b>نقشه فرمان</b><small>CONTROL / LADDER</small></div>${schematicSvg(c.kind,"control")}</section></div><div class="circuit-parts"><b>اجزای اصلی</b><span>${escapeHtml(c.parts)}</span></div><div class="sequence"><b>توالی عملکرد</b><p>${escapeHtml(c.sequence)}</p></div></article>`).join(""):'<div class="empty-state">مداری پیدا نشد.</div>'}
function navigate(page){$$('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+page));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const labels={home:"نمای کلی",calculators:"محاسبات مهندسی",library:"دانشنامه تجهیزات",circuits:"مدارها",history:"تاریخچه محاسبات",about:"درباره برنامه"};$("#pageTitle").textContent=labels[page]||"نمای کلی";$("#sidebar").classList.remove("open");if(page==="history")renderHistory();if(page==="library")renderKnowledge($("#librarySearch").value);if(page==="calculators")renderTools($("#toolSearch").value);if(page==="circuits")renderCircuits($("#circuitSearch").value);window.scrollTo({top:0,behavior:"smooth"})}
document.addEventListener("click",e=>{const tool=e.target.closest("[data-tool]");if(tool){openTool(tool.dataset.tool);return}const go=e.target.closest("[data-go]");if(go){navigate(go.dataset.go);return}const nav=e.target.closest("[data-page]");if(nav){e.preventDefault();navigate(nav.dataset.page)}});
$("#closeModal").addEventListener("click",closeTool);$("#modalBackdrop").addEventListener("click",e=>{if(e.target.id==="modalBackdrop")closeTool()});$("#resetCalc").addEventListener("click",()=>{if(activeTool)openTool(activeTool)});
$("#clearHistory").addEventListener("click",()=>{if(confirm("همه محاسبات ذخیره‌شده پاک شوند؟")){storageRemove(historyKey);storageRemove(legacyHistoryKey);renderHistory();showToast("تاریخچه پاک شد.")}});
$("#toolSearch").addEventListener("input",e=>renderTools(e.target.value));
$("#librarySearch").addEventListener("input",e=>renderKnowledge(e.target.value));
$("#circuitSearch").addEventListener("input",e=>renderCircuits(e.target.value));
$("#menuBtn").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));
$("#themeBtn").addEventListener("click",()=>{document.body.classList.toggle("light");storageSet("cirqvolt_theme",document.body.classList.contains("light")?"light":"dark")});
if(storageGet("cirqvolt_theme")==="light")document.body.classList.add("light");
renderKnowledge();renderHistory();renderTools();renderCircuits();
if("serviceWorker" in navigator && location.protocol!=="file:"){window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(()=>{}))}
function exportBackup(){
  const payload={app:"CirqVolt",format:2,exportedAt:new Date().toISOString(),history:getHistory(),theme:storageGet("cirqvolt_theme","dark")};
  const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");
  a.href=url;a.download=`cirqvolt-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);showToast("نسخه پشتیبان آماده شد.");
}
function importBackup(file){
  if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(data.app!=="CirqVolt"||!Array.isArray(data.history))throw Error("ساختار فایل پشتیبان معتبر نیست.");
    const clean=data.history.filter(x=>x&&typeof x.tool==="string"&&typeof x.value==="string"&&typeof x.at==="string").slice(0,100);
    if(!storageSet(historyKey,JSON.stringify(clean)))throw Error("فضای ذخیره‌سازی مرورگر در دسترس نیست.");renderHistory();showToast(`${clean.length} رکورد بازیابی شد.`);
  }catch(err){showToast(err.message||"خواندن فایل ناموفق بود.");}};reader.readAsText(file);
}
$("#exportBackup")?.addEventListener("click",exportBackup);
$("#importBackup")?.addEventListener("click",()=>$("#backupFile")?.click());
$("#backupFile")?.addEventListener("change",e=>{importBackup(e.target.files?.[0]);e.target.value=""});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("#modalBackdrop").hidden)closeTool()});
